// Guards for the gold ABI fixture files and their loader
// (`test/fixtures/abi`, regenerated by `node scripts/gen-abi-fixtures.mjs`):
// coverage counts, revive semantics, and the byte-verified gold vectors.
import { expect, test } from 'vitest'
import {
  loadEventFixtures,
  loadFunctionFixtures,
  loadPackedFixtures,
  loadParamsFixtures,
  reviveValue,
  reviveValues,
} from '../../fixtures/abi/loader.js'

test('fixture files load with expected coverage', () => {
  expect(loadParamsFixtures().length).toBeGreaterThanOrEqual(45)
  expect(loadFunctionFixtures().length).toBeGreaterThanOrEqual(8)
  expect(loadPackedFixtures().length).toBeGreaterThanOrEqual(15)
  expect(loadEventFixtures().length).toBeGreaterThanOrEqual(6)
})

test('revives scalar bigints and passthrough values', () => {
  const fixtures = loadParamsFixtures()
  const uintMax = fixtures.find((f) => f.name === 'uint256-max')!
  expect(reviveValues(uintMax.params, uintMax.values)).toEqual([
    (1n << 256n) - 1n,
  ])
  const int8Min = fixtures.find((f) => f.name === 'int8-min')!
  expect(reviveValues(int8Min.params, int8Min.values)).toEqual([-128n])
  const address = fixtures.find((f) => f.name === 'address-v3-usdt')!
  expect(reviveValues(address.params, address.values)).toEqual([
    'TA5DvvvmYbS75o3DKtgy2ATAGVHhpFkRLe',
  ])
  const trcToken = fixtures.find((f) => f.name === 'trcToken-scalar')!
  expect(reviveValues(trcToken.params, trcToken.values)).toEqual([1002000n])
})

test('revives nested tuples and arrays positionally', () => {
  const fixtures = loadParamsFixtures()
  const nested = fixtures.find((f) => f.name === 'tuple-nested-tuple')!
  expect(reviveValue(nested.params[0]!, nested.values[0]!)).toEqual([
    42n,
    [
      'TDvSsdrNM5eeXNL3czpa6AxLDHZA9nwe9K',
      '0x0102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f20',
    ],
    'nested',
  ])
  const matrix = fixtures.find((f) => f.name === 'uint256-array-nested')!
  expect(reviveValue(matrix.params[0]!, matrix.values[0]!)).toEqual([
    [1n, 2n],
    [],
    [1000000n],
  ])
})

test('gold vectors survive the JSON round trip', () => {
  const transfer = loadFunctionFixtures().find(
    (f) => f.name === 'trc20-transfer',
  )!
  expect(transfer.calldata).toBe(
    '0xa9059cbb0000000000000000000000000123456789abcdef0123456789abcdef0123456700000000000000000000000000000000000000000000000000000000000f4240',
  )
  const event = loadEventFixtures().find((f) => f.name === 'transfer')!
  expect(event.topics[0]).toBe(
    '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef',
  )
})
